<?php
/**
 * Plugin Name: Khushii Lead & Support Chatbot
 * Description: Guided property enquiry chatbot with lead storage, formatted email and configurable CRM webhook.
 * Version: 1.1.5
 * Requires PHP: 7.4
 */
if (!defined('ABSPATH')) exit;
final class Khushii_Lead_Chatbot {
 const OPT='klc_settings';
 static function init(){ add_action('admin_menu',[__CLASS__,'menu']);add_action('admin_init',[__CLASS__,'settings']);add_action('wp_enqueue_scripts',[__CLASS__,'assets']);add_action('wp_footer',[__CLASS__,'widget']);add_action('rest_api_init',[__CLASS__,'routes']);add_action('admin_post_klc_retry',[__CLASS__,'retry']);add_action('admin_post_klc_test_mail',[__CLASS__,'test_mail']); }
 static function activate(){global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$t=$wpdb->prefix.'klc_leads';$c=$wpdb->get_charset_collate();dbDelta("CREATE TABLE $t (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, created_at datetime NOT NULL, name varchar(120) NOT NULL, email varchar(190) NOT NULL, phone varchar(35) NOT NULL, category varchar(80) NOT NULL, project varchar(120) NOT NULL, location varchar(190) NOT NULL, budget varchar(100) NOT NULL, timeline varchar(100) NOT NULL, message text NOT NULL, consent tinyint(1) NOT NULL DEFAULT 0, page_url text NOT NULL, email_status varchar(25) NOT NULL DEFAULT 'pending', crm_status varchar(25) NOT NULL DEFAULT 'pending', PRIMARY KEY (id), KEY created_at (created_at)) $c;");}
 static function settings(){register_setting('klc_group',self::OPT,['sanitize_callback'=>function($in){$old=get_option(self::OPT,[]);return ['to'=>sanitize_email($in['to']??''),'webhook'=>esc_url_raw($in['webhook']??''),'token'=>trim(sanitize_text_field($in['token']??''))?:($old['token']??''),'enabled'=>empty($in['enabled'])?0:1];}]);}
 static function menu(){add_menu_page('Khushii Chatbot','Khushii Chatbot','manage_options','klc',[__CLASS__,'admin'],'dashicons-format-chat',27);}
 static function admin(){if(!current_user_can('manage_options'))return;$o=get_option(self::OPT,[]);global $wpdb;$t=$wpdb->prefix.'klc_leads';$rows=$wpdb->get_results("SELECT * FROM $t ORDER BY id DESC LIMIT 100");echo '<div class="wrap"><h1>Khushii Lead Chatbot</h1><h2>Delivery settings</h2><form method="post" action="options.php">';settings_fields('klc_group');echo '<table class="form-table"><tr><th>Email recipient</th><td><input class="regular-text" type="email" name="'.self::OPT.'[to]" value="'.esc_attr($o['to']??get_option('admin_email')).'"></td></tr><tr><th>CRM webhook URL (HTTPS)</th><td><input class="large-text" type="url" name="'.self::OPT.'[webhook]" value="'.esc_attr($o['webhook']??'').'"><p class="description">When Khushii CRM Bridge is active, configure delivery there; this legacy webhook is bypassed. Check its queue for confirmed delivery.</p></td></tr><tr><th>Bearer token</th><td><input class="regular-text" type="password" autocomplete="new-password" name="'.self::OPT.'[token]" placeholder="Leave blank to keep existing token"></td></tr><tr><th>Show widget</th><td><label><input type="checkbox" name="'.self::OPT.'[enabled]" value="1" '.checked(!isset($o['enabled'])||$o['enabled'],true,false).'> Enable floating chatbot</label></td></tr></table>';submit_button('Save settings');echo '</form><h2>Email diagnostics</h2><p>The test uses WordPress wp_mail(). A successful handoff does not guarantee inbox delivery. Configure a trusted SMTP mailer if needed.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="klc_test_mail">';wp_nonce_field('klc_test_mail');echo '<p><button class="button button-secondary" type="submit">Send test notification</button></p></form>';if(isset($_GET['klc_mail_test'])){ $result=sanitize_key(wp_unslash($_GET['klc_mail_test']));echo '<div class="notice '.($result==='accepted'?'notice-info':'notice-error').'"><p>'.esc_html($result==='accepted'?'WordPress accepted the test email. Check your inbox/spam and SMTP delivery logs.':'WordPress could not send the test email. Check your SMTP settings and WordPress mail logs.').'</p></div>'; }echo '<h2>Recent leads</h2><div style="overflow:auto"><table class="widefat striped"><thead><tr><th>ID / Date</th><th>Contact</th><th>Enquiry</th><th>Details</th><th>Email</th><th>CRM</th><th>Retry</th></tr></thead><tbody>';foreach($rows as $r){$url=wp_nonce_url(admin_url('admin-post.php?action=klc_retry&id='.$r->id),'klc_retry_'.$r->id);echo '<tr><td>'.esc_html($r->id).' · '.esc_html($r->created_at).'</td><td>'.esc_html($r->name).'<br>'.esc_html($r->email).'<br>'.esc_html($r->phone).'</td><td>'.esc_html($r->category).'<br>'.esc_html($r->project).'</td><td>'.esc_html($r->location).' / '.esc_html($r->budget).' / '.esc_html($r->timeline).'<br>'.esc_html($r->message).'</td><td>'.esc_html($r->email_status).'</td><td>'.esc_html($r->crm_status).'</td><td><a href="'.esc_url($url).'">Retry delivery</a></td></tr>';}echo '</tbody></table></div><p>Last 100 leads. CRM sync requires a compatible webhook. Use HTTPS and configure SMTP for reliable email.</p></div>';}
 static function assets(){if(is_admin())return;$o=get_option(self::OPT,[]);if(isset($o['enabled'])&&!$o['enabled'])return;wp_enqueue_style('klc-css',plugins_url('assets/chat.css',__FILE__),[], '1.1.5');wp_enqueue_script('klc-js',plugins_url('assets/chat.js',__FILE__),[], '1.1.5',true);wp_localize_script('klc-js','KLC_DATA',['endpoint'=>esc_url_raw(rest_url('klc/v1/lead'))]);}
 static function widget(){if(is_admin())return;$o=get_option(self::OPT,[]);if(isset($o['enabled'])&&!$o['enabled'])return;echo '<div id="klc-root"><button id="klc-toggle" type="button" aria-expanded="false" aria-controls="klc-panel" aria-label="Open Khushii Developer chat"><span class="klc-launch-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5 8 8 0 0 1-3-.6L4 20l1.6-4.7A7.5 7.5 0 1 1 20 11.5Z"/><path d="M9 11h.01M12 11h.01M15 11h.01"/></svg></span><span>Chat with us</span></button><section id="klc-panel" role="dialog" aria-label="Khushii Developer enquiry assistant" hidden><header class="klc-head"><div class="klc-brand"><span class="klc-brand-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="6" width="16" height="14" rx="4"/><path d="M12 3v3M9 12h.01M15 12h.01M9 16c2 1 4 1 6 0"/></svg></span><div><strong>Khushii Developer</strong><small><span class="klc-online"></span> Virtual enquiry assistant</small></div></div><button type="button" id="klc-close" aria-label="Close chat" title="Close chat"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6 6 18"/></svg></button></header><div class="klc-progress-wrap"><div class="klc-progress" id="klc-progress"></div></div><div class="klc-step-label" id="klc-step">Start your enquiry</div><div id="klc-messages" aria-live="polite"></div><div id="klc-controls"></div><p class="klc-foot">Secure enquiry · Your details are used to respond to your request</p></section></div>';}
 static function routes(){register_rest_route('klc/v1','/lead',['methods'=>'POST','callback'=>[__CLASS__,'lead'],'permission_callback'=>'__return_true']);}
 static function lead($request){$ip=$_SERVER['REMOTE_ADDR']??'unknown';$key='klc_rate_'.md5($ip);$n=(int)get_transient($key);if($n>=8)return new WP_Error('rate_limit','Too many requests. Please try later.',['status'=>429]);set_transient($key,$n+1,HOUR_IN_SECONDS);$p=$request->get_json_params();if(!is_array($p))return new WP_Error('invalid','Invalid request.',['status'=>400]);if(!empty($p['website']))return new WP_Error('invalid','Invalid submission.',['status'=>400]);$categories=['Project Enquiry','Site Visit','Price & Availability','Documentation','Callback Request','General Support'];$category=sanitize_text_field($p['category']??'');$name=sanitize_text_field($p['name']??'');$email=sanitize_email($p['email']??'');$phone=preg_replace('/[^0-9+()\-\s]/','',strval($p['phone']??''));$digits=preg_replace('/\D/','',$phone);if(!in_array($category,$categories,true)||mb_strlen($name)<2||mb_strlen($name)>120||!is_email($email)||strlen($digits)<10||strlen($digits)>15||($p['consent']??false)!==true)return new WP_Error('validation','Please complete all required fields correctly and accept the contact consent.',['status'=>400]);$data=['created_at'=>current_time('mysql'),'name'=>$name,'email'=>$email,'phone'=>$phone,'category'=>$category,'project'=>sanitize_text_field($p['project']??''),'location'=>sanitize_text_field($p['location']??''),'budget'=>sanitize_text_field($p['budget']??''),'timeline'=>sanitize_text_field($p['timeline']??''),'message'=>sanitize_textarea_field($p['message']??''),'consent'=>1,'page_url'=>esc_url_raw($p['page_url']??'')];foreach(['project','location','budget','timeline'] as $k)$data[$k]=mb_substr($data[$k],0,($k==='location'?190:100));$data['message']=mb_substr($data['message'],0,3000);global $wpdb;$ok=$wpdb->insert($wpdb->prefix.'klc_leads',$data);if(!$ok)return new WP_Error('database','Could not save enquiry. Please try again.',['status'=>500]);$id=(int)$wpdb->insert_id;self::deliver($id);return rest_ensure_response(['success'=>true,'reference'=>'KD-'.str_pad((string)$id,6,'0',STR_PAD_LEFT),'message'=>'Your enquiry has been recorded. Our team can follow up using the details provided.']);}
 static function deliver($id){global $wpdb;$t=$wpdb->prefix.'klc_leads';$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE id=%d",$id),ARRAY_A);if(!$r)return;$o=get_option(self::OPT,[]);$to=is_email($o['to']??'')?$o['to']:get_option('admin_email');$fields=['Reference'=>'KD-'.str_pad((string)$id,6,'0',STR_PAD_LEFT),'Date'=>$r['created_at'],'Enquiry Type'=>$r['category'],'Full Name'=>$r['name'],'Email'=>$r['email'],'Phone'=>$r['phone'],'Project'=>$r['project'],'Preferred Location'=>$r['location'],'Budget'=>$r['budget'],'Timeline'=>$r['timeline'],'Message'=>$r['message'],'Page'=>$r['page_url'],'Consent'=>'Yes'];$rows='';foreach($fields as $k=>$v)$rows.='<tr><th style="text-align:left;padding:11px;background:#edf3f9;border-bottom:1px solid #dbe6ef;width:160px">'.esc_html($k).'</th><td style="padding:11px;border-bottom:1px solid #dbe6ef">'.nl2br(esc_html($v?:'Not specified')).'</td></tr>';$body='<div style="font-family:Arial,sans-serif;max-width:680px;margin:auto;color:#15314d"><div style="background:#102940;color:white;padding:24px"><h2 style="margin:0;color:white">New Khushii Developer Enquiry</h2><p style="margin:8px 0 0;color:#b8d0e3">Automated chatbot lead notification</p></div><table style="width:100%;border-collapse:collapse">'.$rows.'</table></div>';$mail=wp_mail($to,'[Khushii Lead] '.$r['category'].' — '.$r['name'],$body,['Content-Type: text/html; charset=UTF-8','Reply-To: '.sanitize_email($r['email'])]);$wpdb->update($t,['email_status'=>$mail?'sent':'failed'],['id'=>$id]);if(class_exists('Khushii_CRM_Bridge')){$r['enquiry_type']=$r['category'];$queued=Khushii_CRM_Bridge::enqueue('khushii_chatbot',$id,$r);$wpdb->update($t,['crm_status'=>$queued?'queued':'queue_failed'],['id'=>$id]);return;}$webhook=$o['webhook']??'';if(!$webhook){$wpdb->update($t,['crm_status'=>'not_configured'],['id'=>$id]);return;}if(strtolower(wp_parse_url($webhook,PHP_URL_SCHEME)??'')!=='https'){$wpdb->update($t,['crm_status'=>'invalid_url'],['id'=>$id]);return;}$payload=['event'=>'lead.created','source'=>'khushii_chatbot','lead_id'=>$id,'lead'=>$r];$headers=['Content-Type'=>'application/json'];if(!empty($o['token']))$headers['Authorization']='Bearer '.$o['token'];$resp=wp_safe_remote_post($webhook,['timeout'=>12,'redirection'=>0,'headers'=>$headers,'body'=>wp_json_encode($payload)]);$good=!is_wp_error($resp)&&wp_remote_retrieve_response_code($resp)>=200&&wp_remote_retrieve_response_code($resp)<300;$wpdb->update($t,['crm_status'=>$good?'synced':'failed'],['id'=>$id]);}
 static function test_mail(){if(!current_user_can('manage_options'))wp_die('Forbidden');check_admin_referer('klc_test_mail');$o=get_option(self::OPT,[]);$to=is_email($o['to']??'')?$o['to']:get_option('admin_email');$ok=wp_mail($to,'Khushii Chatbot — Test Notification','<p>This is a test email from the Khushii Lead & Support Chatbot.</p><p>If you received it, WordPress was able to hand off a message to your mail service.</p>',['Content-Type: text/html; charset=UTF-8']);wp_safe_redirect(add_query_arg('klc_mail_test',$ok?'accepted':'failed',admin_url('admin.php?page=klc')));exit;}
 static function retry(){if(!current_user_can('manage_options'))wp_die('Forbidden');$id=absint($_GET['id']??0);check_admin_referer('klc_retry_'.$id);self::deliver($id);wp_safe_redirect(admin_url('admin.php?page=klc'));exit;}
}
register_activation_hook(__FILE__,['Khushii_Lead_Chatbot','activate']);Khushii_Lead_Chatbot::init();
